{
  "explanation": "This is Bayes' theorem in action. The disease is rare (1 in 100), so even though the test correctly flags 90% of sick people, it also falsely flags 10% of the much larger healthy population. Those false positives outnumber the true ones, leaving only about an 8.3% chance that a positive result means you actually have the disease.",
  "manimCode": "let prevalence = 0.01;
let accuracy = 0.9;

const title = new Text({ text: "Positive test — what's the chance you're sick?", fontSize: 28, color: WHITE });
title.moveTo([0, 3.5, 0]);
await scene.play(new Write(title));

const formul = new MathTex({ latex: 'P(D|+) = \\frac{P(+|D)P(D)}{P(+|D)P(D)+P(+|\\neg D)P(\\neg D)}' });
await formul.waitForRender();
formul.scale(0.55);
formul.moveTo([0, 2.7, 0]);
await scene.play(new Write(formul));

const hint = new Text({ text: "Drag sliders to explore how rarity & accuracy change the result", fontSize: 16, color: GRAY });
hint.moveTo([0, -3.5, 0]);
scene.add(hint);

let tpCircle = null;
let fpCircle = null;
let tpLabel = null;
let fpLabel = null;
let totalLabel = null;
let resultLabel = null;
let desc1 = null;
let desc2 = null;
let desc3 = null;
let desc4 = null;
let braceLabel = null;

function clearDynamic() {
  [tpCircle, fpCircle, tpLabel, fpLabel, totalLabel, resultLabel, desc1, desc2, desc3, desc4, braceLabel].forEach(m => {
    if (m) scene.remove(m);
  });
}

function updateViz() {
  clearDynamic();
  const N = 1000;
  const sick = N * prevalence;
  const healthy = N - sick;
  const TP = sick * accuracy;
  const FP = healthy * (1 - accuracy);
  const totalPos = TP + FP;
  const post = totalPos > 0 ? (TP / totalPos) * 100 : 0;

  desc1 = new Text({ text: `Imagine ${N} people`, fontSize: 22, color: WHITE });
  desc1.moveTo([-4.2, 1.6, 0]);
  desc2 = new Text({ text: `${sick.toFixed(0)} sick   •   ${healthy.toFixed(0)} healthy`, fontSize: 18, color: BLUE_B });
  desc2.moveTo([-4.2, 1.15, 0]);
  desc3 = new Text({ text: `True positives:  ${TP.toFixed(1)}`, fontSize: 20, color: RED });
  desc3.moveTo([-4.2, 0.5, 0]);
  desc4 = new Text({ text: `False positives:  ${FP.toFixed(1)}`, fontSize: 20, color: ORANGE });
  desc4.moveTo([-4.2, 0.05, 0]);
  scene.add(desc1, desc2, desc3, desc4);

  const tpR = Math.max(0.25, Math.sqrt(TP) * 0.09);
  const fpR = Math.max(0.25, Math.sqrt(FP) * 0.09);

  tpCircle = new Circle({ radius: tpR, color: RED });
  tpCircle.setFill(RED, 0.65);
  tpCircle.moveTo([1.3, 0.3, 0]);

  fpCircle = new Circle({ radius: fpR, color: ORANGE });
  fpCircle.setFill(ORANGE, 0.65);
  fpCircle.moveTo([4.0, 0.3, 0]);

  scene.add(tpCircle, fpCircle);

  tpLabel = new Text({ text: `TP: ${TP.toFixed(1)}`, fontSize: 18, color: WHITE });
  tpLabel.nextTo(tpCircle, DOWN, 0.15);
  fpLabel = new Text({ text: `FP: ${FP.toFixed(1)}`, fontSize: 18, color: WHITE });
  fpLabel.nextTo(fpCircle, DOWN, 0.15);
  scene.add(tpLabel, fpLabel);

  braceLabel = new Text({ text: "← positive tests →", fontSize: 16, color: YELLOW });
  braceLabel.moveTo([2.65, 1.5, 0]);
  scene.add(braceLabel);

  totalLabel = new Text({ text: `Total positives: ${totalPos.toFixed(1)}`, fontSize: 22, color: YELLOW });
  totalLabel.moveTo([2.65, -1.1, 0]);
  scene.add(totalLabel);

  resultLabel = new Text({ text: `P(sick | positive) ≈ ${post.toFixed(1)}%`, fontSize: 30, color: GREEN });
  resultLabel.moveTo([0, -2.3, 0]);
  scene.add(resultLabel);
}

updateViz();

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Prevalence %',
  min: 0.1,
  max: 25,
  value: 1,
  step: 0.1,
  onChange: (v) => {
    prevalence = v / 100;
    updateViz();
  }
});
controls.addSlider({
  label: 'Test accuracy %',
  min: 50,
  max: 99,
  value: 90,
  step: 1,
  onChange: (v) => {
    accuracy = v / 100;
    updateViz();
  }
});
controls.addButton({
  label: 'Reset to 1% / 90%',
  onClick: () => {
    prevalence = 0.01;
    accuracy = 0.9;
    updateViz();
  }
});

await scene.wait(999999);"
